function [values, references, descriptions] = importStructure(filename, startRow, endRow)
%IMPORTFILE Import numeric data from a text file as a matrix.
%   BOUNDARYCONDITIONS = IMPORTFILE(FILENAME) Reads data from text file
%   FILENAME for the default selection.
%
%   BOUNDARYCONDITIONS = IMPORTFILE(FILENAME, STARTROW, ENDROW) Reads data
%   from rows STARTROW through ENDROW of text file FILENAME.
%
% Example:
%   boundaryconditions = importfile('boundary_conditions.txt', 8, 18);
%
%    See also TEXTSCAN.

% Auto-generated by MATLAB on 2019/03/15 14:40:06

%% Initialize variables.
delimiter = '|';
if nargin<=2
    startRow =7;
    endRow = inf;
end

%% Read columns of data as text:
% For more information, see the TEXTSCAN documentation.

if contains(filename,'option')
    formatSpec = '%q%q%q';
    colTxt=[1,3]; colNum=[2];
elseif contains(filename,'settings')
    formatSpec = '%q%q%q%q';
    colTxt=[1,3]; colNum=[2];
elseif contains(filename,'parameters')
    formatSpec = '%q%q%q%q';
    colTxt=[1,3,4]; colNum=[2]; colRef=[3];
elseif contains(filename,'sources')
    formatSpec = '%q%q%q%q';
    colTxt=[1,2,3,4]; colRef=[3];
elseif contains(filename,'montecarlo_ranges')
    formatSpec = '%q%q%q%q%q%q%q%q%q%q';
    colTxt=[1,9,10]; colNum=[2,3,4,5,6,7,8]; colRef=[9];
    valueslist=split("distrib min max mean std adapt round");
elseif contains(filename,'montecarlo_targets')
    formatSpec = '%q%q%q%q';
    colTxt=[1]; colNum=[2,3];
    valueslist=split("value error");
end

if exist('colRef','var');colRef=find(colTxt==colRef);end

%% Open the text file

fileID = fopen(filename,'r');

%% Read columns of data according to the format.

% This call is based on the structure of the file used to generate this
% code. If an error occurs for a different file, try regenerating the code
% from the Import Tool.
textscan(fileID, '%[^\n\r]', startRow(1), 'WhiteSpace', '', 'ReturnOnError', false);
dataArray = textscan(fileID, formatSpec, endRow(1)-startRow(1), 'Delimiter', delimiter, 'TextType', 'string', 'ReturnOnError', false, 'EndOfLine', '\r\n');
for block=2:length(startRow)
    frewind(fileID);
    textscan(fileID, '%[^\n\r]', startRow(block)-1, 'WhiteSpace', '', 'ReturnOnError', false);
    dataArrayBlock = textscan(fileID, formatSpec, endRow(block)-startRow(block)+1, 'Delimiter', delimiter, 'TextType', 'string', 'ReturnOnError', false, 'EndOfLine', '\r\n');
    for col=1:length(dataArray)
        dataArray{col} = [dataArray{col};dataArrayBlock{col}];
    end
end

%% Close the text file

fclose(fileID);

%% Convert the contents of columns containing numeric text to numbers

% Replace non-numeric text with NaN.
raw = repmat({''},length(dataArray{1}),length(dataArray));
for col=1:length(dataArray)
    raw(1:length(dataArray{col}),col) = mat2cell(dataArray{col}, ones(length(dataArray{col}), 1));
end
numericData = NaN(size(dataArray{1},1),size(dataArray,2));

if exist('colNum','var')
    for col=colNum
    % Converts text in the input cell array to numbers. Replaced non-numeric text with NaN.
    rawData = dataArray{col};
    for row=1:size(rawData, 1)
        % Create a regular expression to detect and remove non-numeric prefixes and suffixes.
        regexstr = '(?<prefix>.*?)(?<numbers>([-]*(\d+[\,]*)+[\.]{0,1}\d*[eEdD]{0,1}[-+]*\d*[i]{0,1})|([-]*(\d+[\,]*)*[\.]{1,1}\d+[eEdD]{0,1}[-+]*\d*[i]{0,1}))(?<suffix>.*)';
        try
            result = regexp(rawData(row), regexstr, 'names');
            numbers = result.numbers;
            
            % Detected commas in non-thousand locations.
            invalidThousandsSeparator = false;
            if numbers.contains(',')
                thousandsRegExp = '^\d+?(\,\d{3})*\.{0,1}\d*$';
                if isempty(regexp(numbers, thousandsRegExp, 'once'))
                    numbers = NaN;
                    invalidThousandsSeparator = true;
                end
            end
            % Convert numeric text to numbers.
            if ~invalidThousandsSeparator
                numbers = textscan(char(strrep(numbers, ',', '')), '%f');
                numericData(row, col) = numbers{1};
                raw{row, col} = numbers{1};
            end
        catch
            raw{row, col} = rawData{row};
        end
    end
end
end

i=0;
for col=colTxt
    i=i+1;
    rawTxt(:,i)= dataArray{col};
end

%% Split data into numeric and string columns

if exist('colNum','var')
    rawNumericColumns = numericData(:, colNum);
    rawNumericColumns=num2cell(rawNumericColumns);
end

rawStringColumns = string(rawTxt);
rawStringColumns=regexprep(rawStringColumns, '\t', ' ');

%% Exclude rows with non-numeric cells and commented rows (%)


if exist('colNum','var')
    I = ~all(cellfun(@(x) (isnumeric(x) || islogical(x)),rawNumericColumns),2); % Find rows with non-numeric cells
    rawNumericColumns(I,:) = [];
    rawStringColumns(I,:) = [];
end

if exist('colNum','var');rawNumericColumns = cell2mat(rawNumericColumns);end
rawStringColumns = strtrim(string(rawStringColumns));

if exist('colNum','var')
    I_allNaN = find(all(isnan(rawNumericColumns),2));
    rawNumericColumns(I_allNaN,:) = [];
    rawStringColumns(I_allNaN,:) = [];
end

if exist('colNum','var')
    I = ~cellfun('isempty',(regexpi(rawStringColumns(:,1),'%.*'))); % find index of line not starting with %
    rawStringColumns(I,:) = []; % remove line not starting with %
    rawNumericColumns(I,:) = []; % remove line not starting with %
end

%% Create output variable
values=[];
references=[];
descriptions=[];
for i=1:size(rawStringColumns,1) % change to size(,1) to handle single line txt
    variable=rawStringColumns(i,1);
    if contains(filename,'sources')
        values.(variable)=rawStringColumns(i,2);
    end
    if ~contains(variable,'.')
        if exist('valueslist','var')
            for j=1:length(valueslist)
                item=valueslist(j);
                if exist('colNum','var'); values.(variable).(item)=rawNumericColumns(i,j);end
            end
        else
            if exist('colNum','var'); values.(variable)=rawNumericColumns(i);end
        end
        if exist('colRef','var'); references.(variable)=rawStringColumns(i,colRef);end
        descriptions.(variable)=rawStringColumns(i,end);
    else
        variable=split(variable,'.');
        if exist('colNum','var')
            for j=1:length(valueslist)
                item=valueslist(j);
                if exist('colNum','var'); values.(variable(1)).(variable(2)).(item)=rawNumericColumns(i,j);end
            end
        else
            if exist('colNum','var'); values.(variable(1)).(variable(2)).(item)=rawNumericColumns(i);end
        end
        if exist('colRef','var'); references.(variable(1)).(variable(2))=rawStringColumns(i,colRef);end
        descriptions.(variable(1)).(variable(2))=rawStringColumns(i,end);
    end

end

end

